"""Curated E2 source annotations, independent of search rankings.

Run only after source review; selectors fail if the annotated snapshot changes.
"""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from regnav.core.ingest import load_chunks

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data/official"
chunks = load_chunks(DATA)
manifest = [json.loads(l) for l in (DATA / "manifest.jsonl").read_text(encoding="utf-8").splitlines()]
docs = {m["id"]: m for m in manifest}


def doc(key):
    matches = [did for did, m in docs.items() if key in m["title"]]
    assert len(matches) == 1, (key, matches)
    return matches[0]


def evidence(key, text):
    matches = [c for c in chunks if c.doc_id == doc(key) and text.lower() in c.text.lower()]
    assert matches, (key, text)
    c = matches[0]
    pos = c.text.lower().index(text.lower())
    return {"chunk_id": c.chunk_id, "quote": c.text[pos:pos + len(text)], "locator": c.meta.get("locator"),
            "view_path": c.meta.get("view_path")}


registry = {"snapshot": "2026-11-11", "reviewed_on": "2026-11-12", "documents": {}, "conflicts": []}
for did, m in docs.items():
    registry["documents"][did] = {"title": m["title"], "url": m["url"], "sha256": m["sha256"],
        "issued_on": None, "effective_from": None, "effective_to": None,
        "uncertainty": "Дата начала действия в проверенном тексте не установлена; дата загрузки не является датой действия.",
        "relations": [], "evidence": []}


def annotate(key, issued=None, start=None, uncertainty=None, proofs=(), relations=()):
    registry["documents"][doc(key)].update(issued_on=issued, effective_from=start,
        uncertainty=uncertainty, evidence=[evidence(key, p) for p in proofs], relations=list(relations))


