# Preserve all E1 appendix relations without converting them into effective dates.
relations = json.loads((DATA / "relations.json").read_text(encoding="utf-8"))
for did, edges in relations.items():
    registry["documents"][did]["relations"].extend(edges)
registry["conflicts"].append({"type": "possible_conflict", "doc_ids": [doc("460-1"), doc("3065"), doc("700")],
    "message": "Порядки ФЛС различаются: в старом тексте номер присваивает ПФО, в редакции 3065-1 и порядке 700 — ФЭУ. Прямое основание полной отмены 460-1 в снимке не установлено; не объединяйте старый и новый маршруты согласования.",
    "evidence": [evidence("460-1", "Сотрудник ПФОв течение одного рабочего дня"), evidence("3065", "Сотрудник ФЭУ в течение одного рабочего дня"), evidence("700", "Присвоение номера финансовому лицевому счету осуществляет сотрудник финансово-экономического управления")]})
(DATA / "revisions.json").write_text(json.dumps(registry, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

questions = []


def question(qid, topic, query, targets, elements, applicability="uncertain", as_of="2026-11-12"):
    # Each target is required; alternatives are allowed only within one target.
    expected = [{"doc_id": doc(key), "chunk_ids": [evidence(key, text)["chunk_id"]], "quote": text} for key, text in targets]
    questions.append({"id": qid, "topic": topic, "question": query, "as_of": as_of,
        "expected": expected, "required_elements": elements, "applicability": applicability})


